(function(root){'use strict';const WIDTH=5,ROWS=8,MAX=65536,isValue=n=>Number.isInteger(n)&&n>=2&&n<=MAX&&(n&(n-1))===0,copy=x=>JSON.parse(JSON.stringify(x));
function fresh(){let id=1;return {version:1,cols:[[4,2,8],[2,4],[8,4,2],[4,8],[2,8,4,2]].map(c=>c.map(value=>({id:id++,value}))),serial:id,current:2,next:4,score:0,shots:0,highest:8,bestChain:0,energy:[0,0,0,0,0]}}
function valid(s){if(!s||s.version!==1||!Array.isArray(s.cols)||s.cols.length!==WIDTH||!s.cols.every(c=>Array.isArray(c)&&c.length<=ROWS&&c.every(t=>t&&isValue(t.value)&&Number.isInteger(t.id)&&t.id>0))||!isValue(s.current)||!isValue(s.next))return false;const ids=s.cols.flat().map(t=>t.id);return new Set(ids).size===ids.length&&Number.isInteger(s.serial)&&s.serial>Math.max(0,...ids)&&['score','shots','highest','bestChain'].every(k=>Number.isInteger(s[k])&&s[k]>=0)&&Array.isArray(s.energy)&&s.energy.length===5&&s.energy.every(n=>Number.isFinite(n)&&n>=0&&n<=100)}
function color(value){return (Math.round(Math.log2(value))-1)%5}
function landing(s,col,value=s.current){if(!Number.isInteger(col)||col<0||col>=WIDTH)return null;const c=s.cols[col],full=c.length===ROWS,front=c[c.length-1];if(full&&(!front||front.value!==value||value===MAX))return null;return {col,row:full?ROWS-1:c.length,merge:!!front&&front.value===value&&value<MAX,full}}
function playable(s,value=s.current){return s.cols.some((_,c)=>landing(s,c,value)!==null)}
function over(s){return !playable(s,s.current)&&!playable(s,s.next)}
function locate(cols,id){for(let c=0;c<WIDTH;c++){const r=cols[c].findIndex(t=>t.id===id);if(r>=0)return {c,r,tile:cols[c][r]}}return null}
function ammo(s,rng){const fronts=s.cols.filter(c=>c.length).map(c=>c[c.length-1].value).filter(v=>v<MAX);if(fronts.length&&rng()<.6)return fronts[Math.floor(rng()*fronts.length)];const cap=Math.max(2,Math.min(5,Math.floor(Math.log2(s.highest))-1));return 2**(1+Math.floor(rng()*cap))}
function fire(input,col,rng=Math.random){if(!valid(input))return {ok:false,reason:'state'};const target=landing(input,col);if(!target)return {ok:false,reason:'full'};const s=copy(input),steps=[];let tile,chain=0,damage=0,activeId;
function merge(active,other){const from={c:other.c,r:other.r},old=active.tile.value;active.tile.value*=2;s.cols[other.c].splice(other.r,1);chain++;const gain=active.tile.value*chain;s.score+=gain;s.highest=Math.max(s.highest,active.tile.value);damage+=gain;const k=color(old);s.energy[k]=Math.min(100,s.energy[k]+Math.min(50,old*3));const at=locate(s.cols,activeId);steps.push({type:'merge',cols:copy(s.cols),activeId,col:at.c,row:at.r,from,value:at.tile.value,chain,gain,color:k})}
if(target.full){const old=s.cols[col].pop();tile={id:s.serial++,value:s.current*2};s.cols[col].push(tile);activeId=tile.id;chain=1;const gain=tile.value;s.score+=gain;damage+=gain;s.highest=Math.max(s.highest,tile.value);s.energy[color(old.value)]=Math.min(100,s.energy[color(old.value)]+Math.min(50,old.value*3));steps.push({type:'merge',cols:copy(s.cols),activeId,col,row:ROWS-1,value:tile.value,chain,gain,color:color(old.value)})}else{tile={id:s.serial++,value:s.current};activeId=tile.id;s.cols[col].push(tile);steps.push({type:'land',cols:copy(s.cols),activeId,col,row:target.row,value:tile.value,chain:0})}
for(let safety=0;safety<32;safety++){const a=locate(s.cols,activeId);if(!a||a.tile.value===MAX)break;const candidates=[{c:a.c,r:a.r-1},{c:a.c-1,r:a.r},{c:a.c+1,r:a.r},{c:a.c,r:a.r+1}];const b=candidates.find(p=>p.c>=0&&p.c<WIDTH&&p.r>=0&&s.cols[p.c][p.r]?.value===a.tile.value);if(!b)break;merge(a,{...b,tile:s.cols[b.c][b.r]})}
s.shots++;s.bestChain=Math.max(s.bestChain,chain);if(chain>=3){const bonus=tile.value*chain;s.score+=bonus;damage+=bonus;steps.push({type:'combo',cols:copy(s.cols),activeId,chain,gain:bonus,color:color(tile.value),value:tile.value})}s.current=s.next;s.next=ammo(s,rng);return {ok:true,state:s,steps,target,chain,damage,shotValue:input.current}}
function swap(input){if(!valid(input))return null;const s=copy(input);[s.current,s.next]=[s.next,s.current];return s}
const api={WIDTH,ROWS,MAX,fresh,valid,color,landing,playable,over,fire,swap};root.MCLauncher=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window!=='undefined'?window:globalThis);
